function validate([board]) {
  if (!Array.isArray(board) || board.length !== 3) return 'board must have exactly 3 rows.';
  for (const row of board) {
    if (typeof row !== 'string' || row.length !== 3) return 'Each row must be a string of 3 characters.';
    if (!/^[XO ]{3}$/.test(row)) return "Cells may only be 'X', 'O' or ' '.";
  }
  return null;
}

