function validTicTacToe(board) {
  // Play every possible game from the empty grid and collect each position reached.
  const lines = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
  const target = board.join('');
  const seen = new Set();
  const over = (cells) => cells.indexOf(' ') < 0 || lines.some(([a, b, c]) => cells[a] !== ' ' && cells[a] === cells[b] && cells[b] === cells[c]);
  const stack = [['         ', 'X']];
  while (stack.length) {
    const [cells, turn] = stack.pop();
    if (seen.has(cells)) continue;
    seen.add(cells);
    if (over(cells)) continue;
    for (let k = 0; k < 9; k++) {
      if (cells[k] !== ' ') continue;
      stack.push([cells.slice(0, k) + turn + cells.slice(k + 1), turn === 'X' ? 'O' : 'X']);
    }
  }
  return seen.has(target);
}

