function generate(rand, size) {
  const lines = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
  const won = (cells) => lines.some(([a, b, c]) => cells[a] !== ' ' && cells[a] === cells[b] && cells[b] === cells[c]);
  const cells = Array(9).fill(' ');
  const mode = rand();
  if (mode < 0.3) {
    // Fully random grid: usually invalid.
    for (let k = 0; k < 9; k++) {
      const r = rand();
      cells[k] = r < 0.35 ? 'X' : r < 0.7 ? 'O' : ' ';
    }
  } else {
    // Play a legal game for a random number of moves, sometimes ignoring the end-of-game rule.
    const moves = Math.floor(rand() * 10);
    const ignoreEnd = rand() < 0.3;
    let turn = 'X';
    for (let m = 0; m < moves; m++) {
      if (!ignoreEnd && won(cells.join(''))) break;
      const free = [];
      for (let k = 0; k < 9; k++) if (cells[k] === ' ') free.push(k);
      if (free.length === 0) break;
      cells[free[Math.floor(rand() * free.length)]] = turn;
      turn = turn === 'X' ? 'O' : 'X';
    }
    if (mode > 0.8) {
      // Change one cell to break or keep the turn order.
      const k = Math.floor(rand() * 9);
      const r = rand();
      cells[k] = r < 0.34 ? 'X' : r < 0.67 ? 'O' : ' ';
    }
  }
  return [[cells.slice(0, 3).join(''), cells.slice(3, 6).join(''), cells.slice(6, 9).join('')]];
}
